        setFromX(e.nativeEvent.locationX); }} onResponderMove={e => { if (!disabled)
        setFromX(e.nativeEvent.locationX); }} style={{ flex: 1, height: 44, justifyContent: 'center', opacity: disabled ? .6 : 1 }}>
    <View pointerEvents="none" style={{ height: 4, marginHorizontal: 10, backgroundColor: colors.border, borderRadius: 2 }}/>
    <View pointerEvents="none" style={{ position: 'absolute', left: 10, right: width - 10 - (value + 6) / 12 * (width - 20), height: 4, borderRadius: 2, backgroundColor: '#FB923C' }}/>
    <View pointerEvents="none" style={{ position: 'absolute', left: (value + 6) / 12 * (width - 20), width: 20, height: 20, borderRadius: 10, backgroundColor: colors.selection }}/>
  </View>;
