function CoefficientInput({ label, value, disabled, onChange }) {
    const [draft, setDraft] = useState(String(value));
    useEffect(() => setDraft(String(value)), [value]);
    return <TextInput accessibilityLabel={`${label} value`} value={draft} editable={!disabled} onChangeText={t => { if (!/^-?\d*(\.\d*)?$/.test(t))
        return; setDraft(t); if (t !== '' && t !== '-' && t !== '.' && t !== '-.' && Number.isFinite(Number(t)))
        onChange(Number(t)); }} onBlur={() => setDraft(String(value))} keyboardType="numbers-and-punctuation" selectTextOnFocus maxLength={8} style={{ width: 42, minHeight: 44, textAlign: 'center' }} className="font-poppins-bold text-base text-text-primary border-2 border-border rounded-xl"/>;
}

