import { Text } from 'react-native';
export function ListUIExample() {
    const [value, setValue] = useState('');
    const [selected, setSelected] = useState(false);
    const [notice, setNotice] = useState('');
    let content;
    content = <><ListGroup><ListRow title="Sounds" icon="volume-high" value="On" selected={selected} onPress={() => setSelected(!selected)}/><ListRow title="Daily goal" icon="flag" value="15 XP" onPress={() => setNotice('Goal selected.')}/></ListGroup><EmptyList message="Nothing to review yet."/></>;
