}
@utility ui__body {
  font-family: "Nunito-Regular";
  font-size: 17px;
  line-height: 24px;
}
@utility ui__body-small {
  font-family: "Nunito-Regular";
  font-size: 14px;
  line-height: 20px;
}
@utility ui__label {
  font-family: "Nunito-ExtraBold";
  font-size: 14px;
  line-height: 18px;
}
@utility ui__button-label {
  font-family: "Nunito-ExtraBold";
  font-size: 15px;
  line-height: 20px;
  letter-spacing: 0.6px;
}

/* Profile and Preferences proportions from the supplied 15 October screenshots. */
@utility profile__name {
  font-family: "Nunito-ExtraBold";
  font-size: 26px;
  line-height: 32px;
}
