import { LockedActivity } from '@qentrah/mathing-ui';
import { useState } from 'react';
import { Text, View } from 'react-native';
export function LockedActivityExample() {
    const [notice, setNotice] = useState('');
    let content;
    content = <View className="h-[440px]"><LockedActivity requirement="Pass the counting unit first." onPrerequisite={() => setNotice('Prerequisite callback received.')}/></View>;
    return <>{content}{notice && <Text accessibilityLiveRegion="polite">{notice}</Text>}</>;
}

