import { Action, CourseCard, Heading } from '@qentrah/mathing-ui';
import { useState } from 'react';
import { Text, View } from 'react-native';
export function MathUIExample() {
    const [notice, setNotice] = useState('');
    let content;
    content = <View className="gap-3"><Heading title="One more step" subtitle="A clear action and an optional alternative."/><Action label="Continue" onPress={() => setNotice('Continue selected.')}/><Action secondary label="Review example" onPress={() => setNotice('Review selected.')}/><Action label="Check disabled" disabled onPress={() => { }}/><Action tone="success" label="Correct answer" onPress={() => setNotice('Success action selected.')}/><Action tone="error" label="Try again" onPress={() => setNotice('Retry action selected.')}/><CourseCard title="Number sense" subtitle="Four questions · optional example" onPress={() => setNotice('Course selected.')}/></View>;
    return <>{content}{notice && <Text accessibilityLiveRegion="polite">{notice}</Text>}</>;
}

