import { useState } from 'react';
import { Text, View } from 'react-native';
export function MotionExample() {
    const [value, setValue] = useState('');
    const [selected, setSelected] = useState(false);
    const [play, setPlay] = useState(0);
    let content;
    content = <View className="gap-5"><MotionEntry trigger={play}><MotionReaction reaction={selected ? 'success' : 'retry'}><MathArtwork name="streak" size={72}/></MotionReaction></MotionEntry><MotionProgress value={selected ? 80 : 30}/><MotionPressable accessibilityRole="button" accessibilityLabel="Replay motion examples" onPress={() => { setSelected(!selected); setPlay(play + 1); }} className="min-h-12 bg-brand-soft rounded-xl items-center justify-center"><Text className="ui__button-label text-brand-ink">Replay motion</Text></MotionPressable></View>;
    return content;
}

props.description:
In the absence of auto property, none is much like CSS's none value. box-none is as if you had applied the CSS class:

.box-none {
  pointer-events: none;
}
.box-none * {
  pointer-events: all;
}

box-only is the equivalent of

.box-only {
  pointer-events: all;
}
.box-only * {
  pointer-events: none;
}

But since pointerEvents does not affect layout/appearance, and we are already deviating from the spec by adding additional modes,
we opt to not include pointerEvents on style. On some platforms, we would need to implement it as a className anyways. Using style or not is an implementation detail of the platform.

