import { colors } from '../constants/colors';
import { useEffect } from 'react';
import { Pressable } from 'react-native';
import Animated, { cancelAnimation, Easing, useAnimatedStyle, useSharedValue, withSpring, withTiming } from 'react-native-reanimated';
import { useMotion } from '../hooks/useMotion';
import { useFeedbackPhase } from '../hooks/useFeedbackPhase';
const spring = { damping: 22, stiffness: 360, mass: .65 };
export function MotionPressable({ children, containerStyle, onPressIn, onPressOut, disabled, ...props }) {
    const enabled = useMotion(), press = useSharedValue(0);
    const style = useAnimatedStyle(() => ({ transform: [{ translateY: press.value * 2.5 }, { scale: 1 - press.value * .018 }] }));
    useEffect(() => { if (!enabled || disabled) {
        cancelAnimation(press);
        press.value = 0;
    } return () => cancelAnimation(press); }, [enabled, disabled, press]);
    return <Animated.View style={[containerStyle, style]}><Pressable {...props} disabled={disabled} onPressIn={e => { if (enabled)
        press.value = withTiming(1, { duration: 70 }); onPressIn?.(e); }} onPressOut={e => { press.value = enabled ? withSpring(0, spring) : 0; onPressOut?.(e); }}>{children}</Pressable></Animated.View>;
}
export function MotionEntry({ children, trigger, style }) {
    const enabled = useMotion(), phase = useSharedValue(1);
    useEffect(() => { cancelAnimation(phase); if (!enabled) {
        phase.value = 1;
        return;
    } phase.value = 0; phase.value = withTiming(1, { duration: 210, easing: Easing.out(Easing.cubic) }); return () => cancelAnimation(phase); }, [enabled, trigger, phase]);
    const entry = useAnimatedStyle(() => ({ opacity: phase.value, transform: [{ translateY: (1 - phase.value) * 8 }] }));
    return <Animated.View style={[style, entry]}>{children}</Animated.View>;
}
export function MotionReaction({ children, reaction, style }) {
    const phase = useFeedbackPhase(reaction);
    const motion = useAnimatedStyle(() => {
        const p = phase.value;
        const times = reaction === 'success' ? [0, .18, .44, .76, 1] : [0, .24, .62, 1];
        const values = reaction === 'success' ? [1, .992, 1.022, 1.004, 1] : [1, .994, 1.003, 1];
        let scale = 1;
        if (reaction === 'success' || reaction === 'retry')
            for (let i = 1; i < times.length; i++) {
                if (p <= times[i]) {
                    const t = (p - times[i - 1]) / (times[i] - times[i - 1]);
                    const eased = t * t * t * (t * (6 * t - 15) + 10);
                    scale = values[i - 1] + (values[i] - values[i - 1]) * eased;
                    break;
                }
            }
        return { transform: [{ scale }] };
    });
    return <Animated.View style={[{ transformOrigin: '50% 85%' }, style, motion]}>{children}</Animated.View>;
}
export function MotionProgress({ value }) {
    const enabled = useMotion(), progress = useSharedValue(Math.max(0, Math.min(1, value)));
    useEffect(() => { const next = Math.max(0, Math.min(1, value)); progress.value = enabled ? withTiming(next, { duration: 320, easing: Easing.out(Easing.cubic) }) : next; return () => cancelAnimation(progress); }, [value, enabled, progress]);
    const fill = useAnimatedStyle(() => ({ width: `${progress.value * 100}%` }));
    return <Animated.View style={[{ height: 12, borderRadius: 12, backgroundColor: colors.success, overflow: 'hidden' }, fill]}><Animated.View style={{ height: 3, marginHorizontal: 6, marginTop: 2, borderRadius: 4, backgroundColor: colors.successHighlight }}/></Animated.View>;
}

