import { MatchingPairs } from './MatchingPairs';
import { FractionModel } from './FractionModel';
import { NumberAnswer } from './NumberAnswer';
import { colors } from '../constants/colors';
import { answerParts } from '../data/answerTokens';
import { MotionPressable } from './Motion';
import Animated, { interpolateColor, useAnimatedStyle } from 'react-native-reanimated';
import { useFeedbackPhase } from '../hooks/useFeedbackPhase';
import { useEffect, useMemo, useRef, useState } from 'react';
import { Platform, Text, TextInput, TouchableOpacity, View } from 'react-native';
import Svg, { Circle, Line, Text as SvgText } from 'react-native-svg';
import { FunctionGraph } from './FunctionGraph';
import { Ionicons } from '@expo/vector-icons';
export function QuestionInteraction({ question, value, onChange, disabled, result }) {
    const input = useRef(null);
    const [lineWidth, setLineWidth] = useState(330);
    const kind = question.kind ?? 'choice';
    if (kind === 'match')
        return <MatchingPairs pairs={question.matchPairs ?? []} value={value} onChange={onChange} disabled={disabled}/>;
    if (kind === 'function-graph')
        return <FunctionGraph question={question} value={value} onChange={onChange} disabled={disabled} result={result}/>;
    const answerInput = (label, placeholder) => <View><TextInput ref={input} accessibilityLabel={label} placeholder={placeholder} placeholderTextColor={colors.muted} value={value} onChangeText={onChange} editable={!disabled} autoCapitalize="none" autoCorrect={false} maxLength={120} onSubmitEditing={() => input.current?.blur()} className="font-poppins text-lg text-text-primary border-2 border-b-4 border-border rounded-2xl bg-white px-4 py-3 min-h-14"/>{question.answerFormat && <Text className="body-sm text-text-secondary mt-3">{question.answerFormat.startsWith('Use ^ for powers') ? '^ for powers · * for multiplication' : question.answerFormat}</Text>}</View>;
    if (kind === 'number' && !question.grading)
        return <NumberAnswer value={value} onChange={onChange} disabled={disabled}/>;
    if (kind === 'number' || kind === 'fraction' || kind === 'expression')
        return <AnswerBuilder question={question} value={value} onChange={onChange} disabled={disabled} fallback={answerInput(question.stepLabel ? 'Write this step' : kind === 'expression' ? 'Write the next equation' : 'Write your answer', question.stepLabel ? (question.grading === 'text' ? 'Type the requested word or symbol' : question.grading === 'ordered-values' ? 'Values separated by commas' : kind === 'number' || kind === 'fraction' ? 'Type a number or fraction' : 'Type a mathematical expression') : kind === 'fraction' ? 'e.g. 1/4 or 1 1/3' : kind === 'expression' ? 'e.g. x = 4' : 'Type a number')}/>;
    if (kind === 'order') {
        let steps = [];
        try {
            steps = JSON.parse(value || '[]');
        }
        catch { }
        return <View><View className="border-2 border-border rounded-2xl p-3 min-h-20 mb-4">{!steps.length && <Text className="body-md text-text-secondary p-3">…</Text>}{steps.map((step, i) => <TouchableOpacity key={step} accessibilityRole="button" accessibilityLabel={`Remove step ${i + 1}: ${step}`} disabled={disabled} onPress={() => onChange(JSON.stringify(steps.filter(s => s !== step)))} className="border border-selection bg-white rounded-xl p-2.5 mb-2"><Text className="font-poppins-bold text-brand-text">{i + 1}. {step}</Text></TouchableOpacity>)}</View>{question.options.filter(step => !steps.includes(step)).map(step => <TouchableOpacity key={step} accessibilityRole="button" accessibilityLabel={step} accessibilityState={{ disabled: disabled || steps.includes(step) }} disabled={disabled || steps.includes(step)} onPress={() => onChange(JSON.stringify([...steps, step]))} className={`min-h-11 border-2 border-border rounded-xl p-2.5 mb-2 ${steps.includes(step) ? 'bg-surface' : 'bg-white'}`}><Text className={`font-poppins text-base ${steps.includes(step) ? 'text-text-secondary' : 'text-text-primary'}`}>{step}</Text></TouchableOpacity>)}</View>;
    }
    if (kind === 'fraction-model')
        return <FractionModel denominator={question.denominator ?? 8} value={value} onChange={onChange} disabled={disabled}/>;
    if (kind === 'number-line')
        return <View><View onLayout={event => setLineWidth(event.nativeEvent.layout.width)} style={{ width: 330, maxWidth: '100%', height: 110, alignSelf: 'center' }}><Svg width="100%" height={110} viewBox="0 0 330 110" accessibilityLabel="Number line from minus five to five"><Line x1={15} y1={45} x2={315} y2={45} stroke={colors.muted} strokeWidth={3}/>{Array.from({ length: 11 }, (_, i) => { const n = i - 5, x = 15 + i * 30; return <ViewPoint key={n} x={x} n={n} chosen={value === String(n)} onPress={() => !disabled && onChange(String(n))}/>; })}</Svg>{Platform.OS === 'web' && Array.from({ length: 11 }, (_, i) => <TouchableOpacity key={i} accessible={false} disabled={disabled} onPress={() => onChange(String(i - 5))} style={{ position: 'absolute', left: (15 + i * 30) / 330 * lineWidth - 12, top: 23, width: 24, height: 44 }}/>)}</View>{answerInput('Number line position', 'Type an integer from −5 to 5')}</View>;
    if (kind === 'graph') {
        const coords = value.split(',').map(Number);
        const x = coords[0], y = coords[1];
        const valid = value.includes(',') && Number.isFinite(x) && Number.isFinite(y);
