 return <Svg width={size} height={size} viewBox="0 0 100 100" aria-hidden>
  {rank>=2&&<Path d="M23 65 4 49l7 25 17 9m49-18 19-16-7 25-17 9" fill={tier.shine} stroke={tier.edge} strokeWidth="3" strokeLinejoin="round"/>}
