import { Ionicons } from '@expo/vector-icons';
export function SocialButtonExample() {
    const [notice, setNotice] = useState('');
    let content;
    content = <SocialButton label="Continue with Google" icon={<Ionicons name="logo-google" size={22}/>} onPress={() => setNotice('Provider button preview only.')}/>;
