export function StatsStripExample() {
    const [value, setValue] = useState('');
    const [notice, setNotice] = useState('');
    let content;
    content = <StatsStrip items={[{ label: 'XP', value: 120, icon: 'flash', color: colors.brandText, onPress: () => setNotice('Example XP') }, { label: 'Streak', value: 3, icon: 'flame', color: colors.brandText, onPress: () => setNotice('Example streak') }]}/>;
