  --font-poppins-semibold: "Nunito-ExtraBold";
  --font-poppins-bold: "Nunito-ExtraBold";
}

/* ==============================
   TYPOGRAPHY UTILITIES (BEM)
============================== */

/* h1 — Page / Screen Title: 32px · Bold · 1.2 */
@utility h1 {
  font-family: "Nunito-ExtraBold";
  font-size: 28px;
  font-weight: 700;
  line-height: 34px;
  color: #4B4B4B;
}

/* h2 — Section Title: 24px · SemiBold · 1.3 */
@utility h2 {
  font-family: "Nunito-ExtraBold";
  font-size: 24px;
  font-weight: 600;
  line-height: 31px;
  color: #4B4B4B;
}

/* h3 — Card / Module Title: 20px · SemiBold · 1.3 */
@utility h3 {
  font-family: "Nunito-ExtraBold";
  font-size: 20px;
  font-weight: 600;
  line-height: 26px;
  color: #4B4B4B;
}

/* h4 — Subheading: 16px · Medium · 1.4 */
@utility h4 {
  font-family: "Nunito-Regular";
  font-size: 16px;
  font-weight: 500;
  line-height: 22px;
  color: #4B4B4B;
}

/* body-lg — Important content: 16px · Regular · 1.6 */
@utility body-lg {
  font-family: "Nunito-Regular";
  font-size: 16px;
  font-weight: 400;
  line-height: 26px;
  color: #4B4B4B;
}

/* body-md — Body text: 14px · Regular · 1.6 */
@utility body-md {
  font-family: "Nunito-Regular";
  font-size: 14px;
  font-weight: 400;
  line-height: 22px;
  color: #4B4B4B;
}

/* body-sm — Supporting text: 13px · Regular · 1.6 */
@utility body-sm {
  font-family: "Nunito-Regular";
  font-size: 13px;
  font-weight: 400;
  line-height: 21px;
  color: #4B4B4B;
}

/* caption — Labels, meta text: 11px · Regular · 1.4 */
@utility caption {
  font-family: "Nunito-Regular";
  font-size: 11px;
  font-weight: 400;
  line-height: 15px;
  color: #6F6F6F;
}

/* Web keyboard focus: selection blue, separate from the orange action fill. */
@layer base {
  button:focus-visible, [role="button"]:focus-visible, [role="radio"]:focus-visible,
  [role="tab"]:focus-visible, input:focus-visible, textarea:focus-visible {
    outline: 3px solid var(--color-selection);
    outline-offset: 3px;
  }
}

/* Shared raised surfaces for lists, statistics, and search controls. */
@utility app__card {
  background-color: var(--color-background);
  border: 2px solid var(--color-border);
  border-bottom-width: 2px;
  border-radius: 16px;
}

/* Keep keyboard focus inside its navigation target, away from the bar edge. */
@layer base {
  [role="tab"]:focus-visible {
    outline: 2px solid var(--color-brand-edge);
    outline-offset: -5px;
    border-radius: 16px;
  }
}

/* Explicit type metrics keep NativeWind's text-size defaults from overriding leading. */
@utility ui__title {
  font-family: "Nunito-ExtraBold";
  font-size: 24px;
  line-height: 29px;
}
@utility ui__card-title {
  font-family: "Nunito-ExtraBold";
  font-size: 18px;
