@import "tailwindcss/theme.css" layer(theme);
@import "tailwindcss/preflight.css" layer(base);
@import "tailwindcss/utilities.css";

@import "nativewind/theme";

@theme {
  --color-profile-sky: #84D7FF;
  --color-result-gold: #FFC800;
  --color-result-green: #58CC02;
  --color-result-blue: #1CB0F6;
  --color-brand: #FF9600;
  --color-brand-text: #AD4C00;
  --color-brand-edge: #E77900;
  --color-brand-ink: #4A2600;
  --color-brand-soft: #FFF4E5;
  --color-brand-outline: #FFCB80;
  --color-secondary: #075985;
  --color-secondary-soft: #E5F5FF;
  --color-selection: #1686B0;
  --color-selection-soft: #DDF4FF;
  --color-selection-ink: #075985;
  --color-success: #58CC02;
  --color-success-edge: #58A700;
  --color-success-soft: #D7FFB8;
  --color-success-ink: #174B00;
  --color-success-highlight: #89E219;
  --color-heart: #F94B7C;
  --color-error: #EF4444;
  --color-error-edge: #B91C1C;
  --color-error-soft: #FFDFE0;
  --color-error-ink: #350707;
  --color-reward: #FFC800;
  --color-reward-ink: #76551D;
  --color-text-primary: #4B4B4B;
  --color-text-secondary: #6F6F6F;
  --color-border: #E5E5E5;
  --color-outline: #AFAFAF;
  --color-surface: #F7F7F7;
  --color-background: #FFFFFF;
  --color-lingua-orange: #FF9600;
  --color-lingua-deep-orange: #AD4C00;
  --color-lingua-blue: #1686B0;
  --color-lingua-green: #58CC02;
  --color-warning: #76551D;
  --color-streak: #AD4C00;
  --color-info: #1686B0;

  /* ==============================
     FONT FAMILIES
  ============================== */
  --font-poppins: "Nunito-Regular";
  --font-poppins-medium: "Nunito-Regular";
  --font-poppins-semibold: "Nunito-ExtraBold";
  --font-poppins-bold: "Nunito-ExtraBold";
}

/* ==============================
   TYPOGRAPHY UTILITIES (BEM)
============================== */

/* h1 — Page / Screen Title: 32px · Bold · 1.2 */
@utility h1 {
  font-family: "Nunito-ExtraBold";
  font-size: 28px;
  font-weight: 700;
  line-height: 34px;
  color: #4B4B4B;
}

/* h2 — Section Title: 24px · SemiBold · 1.3 */
@utility h2 {
  font-family: "Nunito-ExtraBold";
  font-size: 24px;
  font-weight: 600;
  line-height: 31px;
  color: #4B4B4B;
}

/* h3 — Card / Module Title: 20px · SemiBold · 1.3 */
@utility h3 {
  font-family: "Nunito-ExtraBold";
  font-size: 20px;
  font-weight: 600;
  line-height: 26px;
  color: #4B4B4B;
}

/* h4 — Subheading: 16px · Medium · 1.4 */
@utility h4 {
  font-family: "Nunito-Regular";
  font-size: 16px;
  font-weight: 500;
  line-height: 22px;
  color: #4B4B4B;
}

/* body-lg — Important content: 16px · Regular · 1.6 */
@utility body-lg {
  font-family: "Nunito-Regular";
  font-size: 16px;
  font-weight: 400;
  line-height: 26px;
  color: #4B4B4B;
}

/* body-md — Body text: 14px · Regular · 1.6 */
@utility body-md {
  font-family: "Nunito-Regular";
  font-size: 14px;
  font-weight: 400;
  line-height: 22px;
  color: #4B4B4B;
}

/* body-sm — Supporting text: 13px · Regular · 1.6 */
@utility body-sm {
  font-family: "Nunito-Regular";
  font-size: 13px;
  font-weight: 400;
  line-height: 21px;
  color: #4B4B4B;
}

/* caption — Labels, meta text: 11px · Regular · 1.4 */
@utility caption {
  font-family: "Nunito-Regular";
  font-size: 11px;
  font-weight: 400;
  line-height: 15px;
  color: #6F6F6F;
}

/* Web keyboard focus: selection blue, separate from the orange action fill. */
@layer base {
  button:focus-visible, [role="button"]:focus-visible, [role="radio"]:focus-visible,
  [role="tab"]:focus-visible, input:focus-visible, textarea:focus-visible {
    outline: 3px solid var(--color-selection);
    outline-offset: 3px;
  }
}

/* Shared raised surfaces for lists, statistics, and search controls. */
@utility app__card {
  background-color: var(--color-background);
  border: 2px solid var(--color-border);
  border-bottom-width: 2px;
  border-radius: 16px;
}

/* Keep keyboard focus inside its navigation target, away from the bar edge. */
@layer base {
  [role="tab"]:focus-visible {
    outline: 2px solid var(--color-brand-edge);
    outline-offset: -5px;
    border-radius: 16px;
  }
}

/* Explicit type metrics keep NativeWind's text-size defaults from overriding leading. */
@utility ui__title {
  font-family: "Nunito-ExtraBold";
  font-size: 24px;
  line-height: 29px;
}
@utility ui__card-title {
  font-family: "Nunito-ExtraBold";
  font-size: 18px;
  line-height: 23px;
}
@utility ui__instruction {
  font-family: "Nunito-ExtraBold";
  font-size: 22px;
  line-height: 28px;
}
@utility ui__math {
  font-family: "Nunito-ExtraBold";
  font-size: 28px;
  line-height: 36px;
}
@utility ui__body {
  font-family: "Nunito-Regular";
  font-size: 17px;
  line-height: 24px;
}
@utility ui__body-small {
  font-family: "Nunito-Regular";
  font-size: 14px;
  line-height: 20px;
}
@utility ui__label {
  font-family: "Nunito-ExtraBold";
  font-size: 14px;
  line-height: 18px;
}
@utility ui__button-label {
  font-family: "Nunito-ExtraBold";
  font-size: 15px;
  line-height: 20px;
  letter-spacing: 0.6px;
}

/* Profile and Preferences proportions from the supplied 15 October screenshots. */
@utility profile__name {
  font-family: "Nunito-ExtraBold";
  font-size: 26px;
  line-height: 32px;
}
@utility profile__section {
  font-family: "Nunito-ExtraBold";
  font-size: 15px;
  line-height: 22px;
  letter-spacing: 0.7px;
}
@utility profile__stat {
  font-family: "Nunito-ExtraBold";
  font-size: 20px;
  line-height: 27px;
}
@utility preferences__label {
  font-family: "Nunito-ExtraBold";
  font-size: 20px;
  line-height: 27px;
}

@source "./src";

