/* Web keyboard focus: selection blue, separate from the orange action fill. */
@layer base {
  button:focus-visible, [role="button"]:focus-visible, [role="radio"]:focus-visible,
  [role="tab"]:focus-visible, input:focus-visible, textarea:focus-visible {
