            screen.mode === 'blanks' || screen.mode === 'table' ? Array.from({ length: blankCount }, (_, i) => cells[i] ?? '').join(',') :
                screen.mode === 'paths' ? String(path.reduce((total, i) => total + numbers[i], 0)) : value;
