import { UIProvider, Action, MathArtwork, MotionReaction, Card } from '@qentrah/mathing-ui';
import { useState } from 'react';
import { Text } from 'react-native';
export function UIProviderExample() {
    const [selected, setSelected] = useState(false);
    let content;
    content = <UIProvider animations={selected}><Card title="Presentation preferences"><Text className="ui__body text-text-secondary">Animations: {selected ? 'on' : 'off'}. System reduced motion is always respected.</Text><Action label="Toggle animations" onPress={() => setSelected(!selected)}/><MotionReaction reaction={selected ? 'success' : 'retry'}><MathArtwork name="streak" size={72}/></MotionReaction></Card></UIProvider>;
    return content;
}

UIProvider.source:
import { createContext, useContext, type ReactNode } from 'react';

export type UIOptions = { animations: boolean };
const Options = createContext<UIOptions>({ animations: true });

/** Optional presentation preferences only. No app stores, accounts, or persistence. */
export function UIProvider({ children, animations = true }: { children: ReactNode; animations?: boolean }) {
  return <Options.Provider value={{ animations }}>{children}</Options.Provider>;
}
export function useUIOptions() { return useContext(Options); }

